function slugify(title) {
  return title
    .trim()
    .toLowerCase()
    .replaceAll("&", "and")
    .replace(/[^a-z0-9\s-]/g, "")   // drop anything that is not a letter, digit, space or hyphen
    .split(/\s+/)
    .filter(Boolean)
    .join("-");
}

console.log(slugify("  Hello Wide World  "));
console.log(slugify("Tips & Tricks: Arrays 101!"));

const cart = [
  { name: "Keyboard", price: 4999, qty: 1 },
  { name: "Mouse", price: 1999, qty: 2 },
  { name: "USB cable", price: 599, qty: 3 },
];

const formatPrice = (cents) => `$${(cents / 100).toFixed(2)}`;

for (const line of cart) {
  console.log(`${line.qty} x ${line.name}: ${formatPrice(line.price * line.qty)}`);
}

const subtotal = cart.reduce((sum, line) => sum + line.price * line.qty, 0);
const shipping = subtotal >= 5000 ? 0 : 499;
console.log(`Subtotal: ${formatPrice(subtotal)}`);
console.log(`Shipping: ${formatPrice(shipping)}`);
console.log(`Total: ${formatPrice(subtotal + shipping)}`);

const text = "the quick brown fox jumps over the lazy dog the end";

const counts = {};
for (const word of text.split(" ")) {
  counts[word] = (counts[word] ?? 0) + 1;
}

const ranked = Object.entries(counts).toSorted((a, b) => b[1] - a[1]);
for (const [word, count] of ranked.slice(0, 3)) {
  console.log(`${word}: ${count}`);
}
console.log(`${Object.keys(counts).length} distinct words`);

class BankAccount {
  #balance = 0;
  #history = [];

  constructor(owner) {
    this.owner = owner;
  }

  get balance() {
    return this.#balance;
  }

  deposit(amount) {
    if (amount <= 0) throw new RangeError("Deposit must be positive");
    this.#balance += amount;
    this.#history.push(`+${amount}`);
    return this;
  }

  withdraw(amount) {
    if (amount > this.#balance) throw new RangeError("Insufficient funds");
    this.#balance -= amount;
    this.#history.push(`-${amount}`);
    return this;
  }

  statement() {
    return `${this.owner}: ${this.#history.join(", ")} = ${this.#balance}`;
  }
}

const account = new BankAccount("Ada");
account.deposit(100).withdraw(30).deposit(5);
console.log(account.balance);
console.log(account.statement());

try {
  account.withdraw(500);
} catch (error) {
  console.log(`${error.name}: ${error.message}`);
}

function parseJsonOr(text, fallback) {
  try {
    return JSON.parse(text);
  } catch (error) {
    console.warn(`Ignoring invalid JSON (${error.name})`);
    return fallback;
  }
}

const saved = parseJsonOr('{"theme":"dark","fontSize":16}', {});
console.log(saved.theme);

const broken = parseJsonOr("{theme: dark}", { theme: "light" });
console.log(broken.theme);

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function countdown(from) {
  for (let n = from; n > 0; n--) {
    console.log(n);
    await sleep(300);
  }
  console.log("Lift-off!");
}

countdown(3);
console.log("Counting in the background...");
